UPDATE lessons SET title='Year 3, Week 33, Lesson 3: Direct speech review', data=json_patch(data,'{"child_mission":"Direct speech review consolidates quotation marks, capitals, commas/reporting clauses and end marks.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nPunctuate: the bird warned run to the ridge\n\nFEEDBACK\nThe bird warned, \"Run to the ridge!\"\n\nCHECK\nMissing commas or end marks inside/outside quotes are common errors to hunt.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nPunctuate ten direct speech sentences (including interrupted quotes). Rewrite a dialogue of six lines from your folktale with accurate speech punctuation.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Direct speech review consolidates quotation marks, capitals, commas/reporting clauses and end marks.","lesson_number":3,"lesson_role":"Language and spelling","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-VOCAB-01","EN2-SPELL-01"],"parent_notes":"Parent: Marking guidance for the independent task: Punctuate ten direct speech sentences (including interrupted quotes). Rewrite a dialogue of six lines from your folktale with accurate speech punctuation. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: The bird warned, \"Run to the ridge!\" Reasonin